script:
cd "$env:USERPROFILE\Desktop\audit2"
"=== pull latest code ==="
git pull -q origin main 2>&1 | Select-Object -Last 3
git log --oneline -1
"=== kill any stray pipeline workers ==="
Get-CimInstance Win32_Process -Filter "Name='python.exe'" | Where-Object { $_.CommandLine -like "*main.py*" } | ForEach-Object { Stop-Process -Id $_.ProcessId -Force; "killed $($_.ProcessId)" }
"no strays" 
"=== dashboard ==="
$tsip = (tailscale ip -4 2>$null | Select-Object -First 1)
if ($tsip) { $tsip = $tsip.Trim() } else { $tsip = "0.0.0.0" }
"binding to: $tsip"
try {
  Invoke-WebRequest -Uri "http://${tsip}:8472/api/status" -TimeoutSec 3 -UseBasicParsing | Out-Null
  "dashboard already running"
} catch {
  Start-Process -FilePath ".\.venv\Scripts\python.exe" -ArgumentList "status_server.py --config tests/test_config.yaml --host $tsip --port 8472" -WindowStyle Hidden
  Start-Sleep -Seconds 4
  try {
    $r = Invoke-WebRequest -Uri "http://${tsip}:8472/api/status" -TimeoutSec 5 -UseBasicParsing
    "dashboard started OK on ${tsip}:8472"
  } catch {
    "DASHBOARD START FAILED: " + $_.Exception.Message
  }
}
"=== checkpoint state ==="
& .\.venv\Scripts\Activate.ps1
python -c "
import sqlite3
con = sqlite3.connect('testdata/audit_out/checkpoints.sqlite')
rows = list(con.execute('select path, last_frame, status from videos'))
print('checkpoint rows:', len(rows))
for r in rows: print(' ', r[0].replace(chr(92),'/').split('/')[-1], r[1], r[2])
"
